const standardized = [];

function processItem(raw, defaultSource) {
  if (!raw || typeof raw !== 'object') return null;
  if (raw.legal && !raw.position && !raw.title) return null;

  let source = defaultSource || raw.source || 'unknown';
  let id = '';
  let title = '';
  let company = '';
  let description = '';
  let url = '';
  let published_at = '';
  let salary_raw = null;

  if (source === 'arbeitnow' || (raw.slug && raw.company_name)) {
    source = 'arbeitnow';
    id = String(raw.slug || raw.id || '');
    title = raw.title || '';
    company = raw.company_name || '';
    description = raw.description || '';
    url = raw.url || '';
    published_at = raw.created_at ? (typeof raw.created_at === 'number' ? new Date(raw.created_at * 1000).toISOString() : new Date(raw.created_at).toISOString()) : new Date().toISOString();
    salary_raw = raw.salary || null;
  } else if (source === 'jobicy' || raw.jobTitle || raw.companyName) {
    source = 'jobicy';
    id = String(raw.id || raw.jobSlug || '');
    title = raw.jobTitle || raw.title || '';
    company = raw.companyName || raw.company || '';
    description = raw.jobDescription || raw.description || '';
    url = raw.url || '';
    published_at = raw.pubDate ? new Date(raw.pubDate).toISOString() : new Date().toISOString();
    if (raw.salaryMin || raw.salaryMax) {
      const curr = raw.salaryCurrency || '$';
      const period = raw.salaryPeriod ? ' / ' + raw.salaryPeriod : '';
      salary_raw = `${curr}${raw.salaryMin || 0} - ${curr}${raw.salaryMax || 0}${period}`;
    }
  } else if (source === 'remoteok' || raw.position) {
    source = 'remoteok';
    id = String(raw.id || raw.slug || '');
    title = raw.position || raw.title || '';
    company = raw.company || '';
    description = raw.description || '';
    url = raw.url ? (raw.url.startsWith('http') ? raw.url : 'https://remoteok.com' + raw.url) : (raw.apply_url || '');
    published_at = raw.date ? new Date(raw.date).toISOString() : (raw.epoch ? new Date(raw.epoch * 1000).toISOString() : new Date().toISOString());
    if (raw.salary_min || raw.salary_max) {
      salary_raw = `$${raw.salary_min || 0} - $${raw.salary_max || 0}`;
    }
  } else {
    id = String(raw.id || raw.slug || Math.random().toString(36).substring(2, 9));
    title = raw.title || raw.jobTitle || raw.position || '';
    company = raw.company || raw.companyName || raw.company_name || '';
    description = raw.description || raw.jobDescription || '';
    url = raw.url || '';
    published_at = raw.published_at || raw.date || raw.created_at || new Date().toISOString();
    salary_raw = raw.salary_raw || raw.salary || null;
  }

  if (!title && !description) return null;

  return {
    id,
    title: title.trim(),
    company: company.trim(),
    description,
    url: url.trim(),
    published_at,
    salary_raw,
    source
  };
}

for (const item of $input.all()) {
  const data = item.json;
  if (!data) continue;

  if (Array.isArray(data.data)) {
    for (const job of data.data) {
      const std = processItem(job, 'arbeitnow');
      if (std) standardized.push({ json: std });
    }
  } else if (Array.isArray(data.jobs)) {
    for (const job of data.jobs) {
      const std = processItem(job, 'jobicy');
      if (std) standardized.push({ json: std });
    }
  } else if (Array.isArray(data)) {
    for (const job of data) {
      const std = processItem(job, 'remoteok');
      if (std) standardized.push({ json: std });
    }
  } else {
    const std = processItem(data);
    if (std) standardized.push({ json: std });
  }
}

if (standardized.length === 0) {
  try {
    const fs = require('fs');
    const path = require('path');
    const mockPath = path.resolve('test/mock_jobs.json');
    if (fs.existsSync(mockPath)) {
      const mockData = JSON.parse(fs.readFileSync(mockPath, 'utf8'));
      for (const job of mockData) {
        const std = processItem(job, job.source || 'mock');
        if (std) standardized.push({ json: std });
      }
    }
  } catch (e) {}
}

return standardized;

